/**
 * Orchestration types — how the app-side "celebration" maps to Swiggy MCP reality.
 *
 * Constraints baked into this model (from Swiggy MCP docs):
 *   1. Food carts are single-restaurant. Switching restaurants flushes the cart.
 *      → A celebration with N restaurants = N independent Swiggy food orders.
 *   2. ₹1000 hard cap per food order.
 *      → Each SubOrder.subtotal must stay under cap; UI must enforce.
 *   3. COD-only in v1. No native online payment, no Swiggy-side UPI split.
 *      → Settlement.upiLinks are generated by THIS app, post-delivery.
 *   4. No scheduled delivery on either MCP server.
 *      → "Synced delivery" = staggering placement times based on observed ETAs.
 *      → "15-min pre-drop" = Instamart's faster ETA (10–20m) vs Food (~25–40m).
 *   5. place_food_order is NOT idempotent. 5xx retries must verify via get_food_orders.
 *   6. Tracking poll cadence: no faster than every 10s per order.
 */

import type { CartLine } from '../state/CelebrationContext';
import type { Member } from '../data/mock';
import type { Product } from '../lib/mcp/types';

// --- Per-order primitives ----------------------------------------------------

export type SubOrderKind = 'food' | 'instamart';

export type SubOrderStatus =
  | 'draft'        // building the sub-cart in our app, not yet pushed to Swiggy
  | 'queued'       // scheduler picked a placement time; waiting to fire
  | 'placing'      // place_food_order / checkout in flight
  | 'placed'       // Swiggy accepted, orderId returned
  | 'preparing'    // restaurant confirmed
  | 'on-the-way'
  | 'delivered'
  | 'cancelled'
  | 'failed';      // place call returned 5xx; needs reconciliation via get_food_orders

export type FoodSubOrder = {
  kind: 'food';
  id: string;                     // app-local id
  restaurantId: string;           // Swiggy restaurant id
  restaurantName: string;
  lines: CartLine[];              // re-use existing app type
  subtotal: number;               // food only, ex coupons/delivery
  coupon?: { code: string; discount: number };
  capExceeded: boolean;           // subtotal > 1000 → block placement
  // MCP-side state
  swiggyOrderId?: string;         // place_food_order → orderId
  placementOffsetMs: number;      // when to fire, relative to celebration "go" time
  scheduledFor: string | null;    // ISO timestamp the scheduler picked
  placedAt: string | null;        // ISO when place_food_order actually returned
  etaMinutes: number | null;      // from track_food_order
  status: SubOrderStatus;
  lastError?: { code: string; message: string; at: string };
};

export type InstamartLine = {
  spinId: string;                 // Instamart SKU id (from search_products)
  name: string;
  qty: number;
  unitPrice: number;
};

export type InstamartSubOrder = {
  kind: 'instamart';
  id: string;
  lines: InstamartLine[];
  // Source of each line — useful for the "pantry-aware" pillar
  source: Array<{ spinId: string; from: 'go-to' | 'cuisine-pair' | 'host-pick' }>;
  subtotal: number;
  // No cap on Instamart (min ₹99 per docs)
  swiggyOrderId?: string;
  placementOffsetMs: number;      // typically NEGATIVE — place this FIRST so it arrives early
  scheduledFor: string | null;
  placedAt: string | null;
  etaMinutes: number | null;
  status: SubOrderStatus;
  lastError?: { code: string; message: string; at: string };
};

export type SubOrder = FoodSubOrder | InstamartSubOrder;

// --- Placement scheduling ----------------------------------------------------

/**
 * Computed once at "checkout". Each SubOrder gets a placementOffsetMs relative to T=0.
 * Goal: all food deliveries land within ~5 min of each other; Instamart lands ~15 min earlier.
 *
 * Inputs: per-restaurant historical ETA estimate (you may have to estimate from prior orders
 *         or restaurant.avgPrepTime). MCP doesn't expose pre-order ETAs.
 */
export type PlacementPlan = {
  computedAt: string;                       // ISO
  targetConvergenceMinutes: number;         // tolerance for "lands together" (e.g. 5)
  preDropLeadMinutes: number;               // e.g. 15 — but this is a TARGET not a guarantee
  entries: Array<{
    subOrderId: string;
    estimatedEtaMin: number;                // our best guess at total time-to-doorstep
    fireAt: string;                         // ISO — when scheduler should call place_*
  }>;
};

// --- Settlement (app-side, NOT Swiggy) ---------------------------------------

export type SettlementShare = {
  memberId: string;
  // Sum of: (their food lines across all FoodSubOrders) + (their share of group items)
  amount: number;
  // Which sub-orders contributed
  contributions: Array<{ subOrderId: string; amount: number }>;
  paid: boolean;
  upiLink?: string;                         // deeplink we generate (upi://pay?...)
  paidAt?: string;
};

export type Settlement = {
  mode: 'equal' | 'by-item';
  shares: SettlementShare[];
  total: number;
  // Note: Swiggy collects COD per-order from whoever opens the door.
  // Settlement reconciles those payments after the fact.
  cashCollectedFrom?: string;               // memberId — host usually pays COD, others UPI them
};

// --- The app-level "Celebration" wrapper -------------------------------------

export type Celebration = {
  id: string;
  occasionId: string;
  hostId: string;
  members: Member[];
  address: string;                          // free text for UI; mapped to addressId at checkout
  addressId?: string;                       // from get_addresses; required before any MCP call
  subOrders: SubOrder[];
  preDropPack: Product[];                   // real Instamart products; becomes the InstamartSubOrder.lines
  plan?: PlacementPlan;
  settlement?: Settlement;
  status: 'planning' | 'placing' | 'in-flight' | 'completed' | 'failed';
  createdAt: string;
};

// --- Mapping cheatsheet ------------------------------------------------------
//
//  This app concept              →  MCP tool                          →  Server
//  ──────────────────────────────────────────────────────────────────────────────
//  resolve user's address        →  get_addresses                     →  Food + Instamart
//  pick restaurants              →  search_restaurants (per addressId) →  Food
//  build per-restaurant cart     →  update_food_cart (one call per     →  Food
//                                   restaurant — NOT one per cart!)
//  auto-apply best coupon        →  fetch_food_coupons + apply_food_coupon → Food
//  confirm sub-cart              →  get_food_cart                     →  Food
//  fire each food order          →  place_food_order  (paymentMethod=COD) → Food
//  build pre-drop pack lines     →  your_go_to_items + search_products →  Instamart
//  build instamart cart          →  update_cart                       →  Instamart
//  fire instamart order          →  checkout (paymentMethod=COD)      →  Instamart
//  poll live status              →  track_food_order, track_order     →  both
//  reconcile after 5xx           →  get_food_orders, get_orders       →  both
//
//  App-only (no MCP equivalent): PlacementPlan, Settlement, UPI links, group cart UI
